"""
    :param h1: string with text for HTML header
    :return:  string containing HTML header 1
    """
def h1(text: str) -> object {
    if not isinstance(text, str) {
        raise TypeError("input must be a string");
    }
    local_text = """<h1>""" + text + """</h1>
    """;
    return local_text;
}

